from pathlib import Path
p=Path('MER_VIS_review_tool/app.js');s=p.read_text(encoding='utf8')
s=s.replace("'showRejected','unwrapPA'", "'showRejected','showWarnings','unwrapPA'",1);s=s.replace('showRejected:true,unwrapPA:true','showRejected:true,showWarnings:true,unwrapPA:true',1)
pos=s.index('function drawProfiles(){')
helper='''function profileWarningEvidence(g,settings,c){
 if(!c||!Array.isArray(c.disc)||!Array.isArray(c.bar))return [];
 const issues=c.issues??[],has=text=>issues.some(v=>v.startsWith(text)),warnings=[],disc=c.disc,bar=c.bar,r=settings.rules;
 const add=(code,label,detail,points=[])=>warnings.push({code,label,detail,points});
 if(has('Fit failed')){add('failed','No adopted fit',g.fit_error||'No reliable geometry was adopted. Empty profiles do not establish that the galaxy has no bar.');return warnings;}
 if(has('Changing disc ellipticity')){const valid=disc.filter(p=>finite(p.ellipticity));if(valid.length){const low=valid.reduce((a,b)=>a.ellipticity<b.ellipticity?a:b),high=valid.reduce((a,b)=>a.ellipticity>b.ellipticity?a:b);add('ellipticity','Changing disc ellipticity',`Selected ε low ${fmt(low.ellipticity,3)}, high ${fmt(high.ellipticity,3)}; Δε ${fmt(c.eps_span,3)} > screen ${fmt(r.eps_span,3)}. The bracket joins these selected measurements, not the grey excluded samples.`,[low,high]);}}
 if(has('Sparse disc sampling')||has('Fewer than three disc ellipses')){const ordered=disc.slice().sort((a,b)=>a.sma_arcsec-b.sma_arcsec);let gap=[];for(let i=1;i<ordered.length;i++)if(!gap.length||ordered[i].sma_arcsec-ordered[i-1].sma_arcsec>gap[1].sma_arcsec-gap[0].sma_arcsec)gap=[ordered[i-1],ordered[i]];
 const reason=c.n_disc<3?'Fewer than 3 selected samples: no trial disc geometry.':`${c.n_disc<r.min_disc?`Count ${c.n_disc} < required ${r.min_disc}. `:''}${c.max_gap_fraction>r.max_gap?`Gap ${(c.max_gap_fraction*100).toFixed(1)}% > limit ${(r.max_gap*100).toFixed(1)}%. `:''}`;
 add('sampling','Sparse disc sampling',`${c.n_disc} selected disc ellipses. ${reason}Largest internal gap ${gap.length?fmt(gap[1].sma_arcsec-gap[0].sma_arcsec)+'″':'not measurable'}; selected radial span ${fmt(c.span_arcsec)}″. Rings identify selected samples; the amber strip marks the largest gap, including any excluded measurements.`,disc);warnings.at(-1).gap=gap;}
 if(has('Disc PA varies across radius')){add('pa','Disc PA variation',`Axial RMS ${fmt(c.pa_scatter)}° > screen ${fmt(r.pa_rms)}°, from ${disc.length} selected disc ellipses. Orange stems show deviations from the unweighted axial mean used by the RMS test (not necessarily the error-weighted reported Disc PA).`,disc);warnings.at(-1).mean=axialMean(disc.map(p=>p.pa_sky_deg));}
 if(has('Small candidate feature'))add('smallbar','Small candidate bar',`Bar outer radius ${fmt(settings.bar[1])}″ < screen ${fmt(r.small_bar)}″. This criterion tests outer radius, not interval width; it does not prove a bar is absent.`,bar);
 if(has('Selected bar interval does not pass'))add('bar','Bar signature not accepted',`${bar.length} selected bar ellipses; PA RMS ${fmt(c.bar_scatter)}°; smoothed ellipticity peak ${fmt(c.bar_peak,3)}; outward drop ${fmt(c.bar_drop,3)}. The shaded bar interval is outlined for inspection; lack of acceptance is not proof that no bar exists.`,bar);
 if(has('Weaker B-style'))add('bar','Class B bar evidence',`Bar grade ${c.bar_grade}; ${bar.length} selected ellipses, PA RMS ${fmt(c.bar_scatter)}°, smoothed peak ε ${fmt(c.bar_peak,3)}, outward drop ${fmt(c.bar_drop,3)}. Class B passes the common bar screen but misses at least one stronger Class A requirement. Stored grades refer to the original fit.`,bar);
 return warnings;
}
function drawWarningGraphics(warnings,{id,x,y,value,top,ph,left,right,xmax,paView}){
 let out='';const ring=(p,color)=>{const v=value(p);if(!finite(v)||!finite(p.sma_arcsec)||p.sma_arcsec>xmax)return '';return `<circle class="warning-point" cx="${x(p.sma_arcsec)}" cy="${y(v)}" r="5.5" fill="none" stroke="${color}" stroke-width="1.8"/>`;};
 const note=(px,py,text,color)=>`<text x="${clamp(px,left+3,right-120)}" y="${clamp(py,top+45,top+ph-5)}" style="fill:${color};stroke:white;stroke-width:3px;paint-order:stroke;font-size:12px">${esc(text)}</text>`;
 for(const w of warnings){let mark='';const color=w.code==='ellipticity'?'#b13b79':'#ad5b00';
  if(w.code==='ellipticity'&&(id==='epsPlot'||id==='incPlot')){const [low,high]=w.points,a=value(low),b=value(high);if(finite(a)&&finite(b)){const bx=clamp(Math.max(x(low.sma_arcsec),x(high.sma_arcsec))+12,left+8,right-10);mark+=w.points.map(p=>ring(p,color)+`<line x1="${x(p.sma_arcsec)}" x2="${bx}" y1="${y(value(p))}" y2="${y(value(p))}" stroke="${color}" stroke-dasharray="2 3"/>`).join('');mark+=`<path class="warning-range" d="M ${bx-4} ${y(a)} H ${bx+4} M ${bx} ${y(a)} V ${y(b)} M ${bx-4} ${y(b)} H ${bx+4}" fill="none" stroke="${color}" stroke-width="2"/>`;mark+=note(bx+8,(y(a)+y(b))/2,id==='epsPlot'?`Δε ${fmt(Math.abs(b-a),3)}`:`Δi ${fmt(Math.abs(b-a))}°`,color);}}
  if(w.code==='sampling'){mark+=w.points.map(p=>ring(p,color)).join('');if(w.gap?.length){const [a,b]=w.gap;mark+=`<rect class="warning-gap" x="${x(a.sma_arcsec)}" y="${top+ph-10}" width="${Math.max(0,x(b.sma_arcsec)-x(a.sma_arcsec))}" height="9" fill="#df9a23" opacity=".65"/>`;}mark+=note(left+8,top+ph-16,`Disc n=${w.points.length}; gap ${fmt(S.calc.max_gap_fraction*100,0)}%`,color);}
  if(w.code==='pa'&&id==='paPlot'){for(const p of w.points){const v=value(p);if(!finite(v))continue;const mean=w.mean+180*Math.round((v-w.mean)/180);mark+=ring(p,color)+`<line class="warning-pa-residual" x1="${x(p.sma_arcsec)}" x2="${x(p.sma_arcsec)}" y1="${y(v)}" y2="${y(clamp(mean,paView.min,paView.max))}" stroke="${color}" stroke-width="1.7"/>`;}mark+=note(left+8,top+ph-16,`Disc PA RMS ${fmt(S.calc.pa_scatter)}°`,color);}
  if((w.code==='smallbar'||w.code==='bar')&&(id==='epsPlot'||id==='paPlot')){const bounds=S.settings.bar,start=x(clamp(bounds[0],0,xmax)),end=x(clamp(bounds[1],0,xmax));mark+=`<rect class="warning-bar-range" x="${start}" y="${top+1}" width="${Math.max(0,end-start)}" height="${ph-2}" fill="none" stroke="${color}" stroke-width="1.6" stroke-dasharray="3 3"/>`;if(id==='epsPlot')mark+=note(start,top+ph-(w.code==='smallbar'?32:48),w.code==='smallbar'?`Bar end ${fmt(bounds[1])}″ < ${fmt(S.settings.rules.small_bar)}″`:w.label,color);}
  if(mark)out+=`<g class="profile-warning" data-warning="${w.code}" style="pointer-events:none"><title>${esc(w.detail)}</title>${mark}</g>`;
 }
 return out;
}
'''
s=s[:pos]+helper+s[pos:]
s=s.replace("const accepted=pool(),acceptedSet=new Set(accepted),xmax=plotMax(),paView=", "const warnings=profileWarningEvidence(S.g,S.settings,S.calc),highlight=S.settings.display.showWarnings!==false;\n $('profileWarnings').innerHTML=highlight?warnings.map(w=>`<div class=\"profile-warning-note\"><strong>${esc(w.label)}:</strong> ${esc(w.detail)}</div>`).join(''):'';\n const accepted=pool(),acceptedSet=new Set(accepted),xmax=plotMax(),paView=",1)
needle=' html+=`<rect x="${left}" y="${top}" width="${pw}" height="${ph}" fill="none" stroke="#7e929f"/>`;'
s=s.replace(needle, " if(highlight)html+=drawWarningGraphics(warnings,{id,x,y,value,top,ph,left,right:w-right,xmax,paView});\n"+needle,1)
s=s.replace("else if(id==='unwrapPA')drawProfiles();", "else if(id==='unwrapPA'||id==='showWarnings')drawProfiles();")
s=s.replace('state:S,calculate,resetGalaxyOverlays,','state:S,calculate,profileWarningEvidence,drawWarningGraphics,resetGalaxyOverlays,');p.write_text(s,encoding='utf8')
p=Path('MER_VIS_review_tool/index.html');s=p.read_text(encoding='utf8');s=s.replace('<h2>Ellipse profiles</h2>', '<h2>Ellipse profiles</h2><label class="check"><input id="showWarnings" type="checkbox" checked> Highlight warnings</label>',1);s=s.replace('   <div class="profile-help">', '   <div id="profileWarnings" aria-live="polite"></div>\n   <div class="profile-help">',1);p.write_text(s,encoding='utf8')
p=Path('MER_VIS_review_tool/style.css');s=p.read_text(encoding='utf8');s+='\n.profile-panel .panel-heading{flex-wrap:wrap}.profile-warning-note{font-size:12px;line-height:1.45;padding:7px 10px;margin:6px 0;background:#fff5e7;border-left:3px solid #ad5b00;border-radius:3px}#profileWarnings{margin-top:10px}\n';p.write_text(s,encoding='utf8')
